evaluate_script: install harness H (idempotent; returns 'installed' or 'already'). PASTE EXACTLY — every other pianoroll case refers to this snippet as 'harness H':
() => {
  if (window.__prh) return 'already';
  const P = Element.prototype;
  const orig = { s: P.setPointerCapture, r: P.releasePointerCapture, h: P.hasPointerCapture };
  P.setPointerCapture = function () {}; P.releasePointerCapture = function () {}; P.hasPointerCapture = function () { return false; };
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const frames = () => new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
  const ev = (el, type, x, y, o) => { o = o || {}; const r = el.getBoundingClientRect(); el.dispatchEvent(new PointerEvent(type, { bubbles: true, cancelable: true, composed: true, pointerId: 1, pointerType: 'mouse', isPrimary: true, clientX: r.left + x, clientY: r.top + y, button: o.button || 0, buttons: o.buttons || 0, shiftKey: !!o.shiftKey, altKey: !!o.altKey, ctrlKey: !!o.ctrlKey })); };
  const H = { sleep, frames, ev,
    restore: () => { P.setPointerCapture = orig.s; P.releasePointerCapture = orig.r; P.hasPointerCapture = orig.h; delete window.__prh; },
    key: (k, o) => window.dispatchEvent(new KeyboardEvent('keydown', Object.assign({ key: k, bubbles: true, cancelable: true }, o || {}))),
    click: (el, x, y, o) => { ev(el, 'pointerdown', x, y, Object.assign({}, o, { buttons: 1 })); ev(el, 'pointerup', x, y, Object.assign({}, o, { buttons: 0 })); },
    drag: async (el, x0, y0, x1, y1, o, n) => { n = n || 6; ev(el, 'pointerdown', x0, y0, Object.assign({}, o, { buttons: 1 })); for (let i = 1; i <= n; i++) ev(el, 'pointermove', x0 + (x1 - x0) * i / n, y0 + (y1 - y0) * i / n, Object.assign({}, o, { buttons: 1 })); ev(el, 'pointerup', x1, y1, Object.assign({}, o, { buttons: 0 })); await frames(); },
    notes: () => document.querySelector('.pr-notes-wrap canvas:not(.pr-overlay-canvas)'),
    keysCv: () => document.querySelector('.pr-keys-wrap canvas'),
    lane: (i) => document.querySelectorAll('.pr-vel-wrap canvas')[i || 0],
    count: () => { const e = document.querySelector('.pr-count'); return e ? e.textContent.trim() : null; },
    len: () => { const e = document.querySelector('.pr-len'); return e ? e.textContent.trim() : null; },
    pct: () => { const d = document.querySelector('.pr-notes-wrap [role="spinbutton"]'); return d ? Number(d.getAttribute('aria-valuenow')) : null; },
    snap: (el) => ({ k: el.width / Math.max(1, el.clientWidth), w: el.width, h: el.height, d: el.getContext('2d').getImageData(0, 0, el.width, el.height).data }),
    bbox: (a, b, thr, xlo, xhi) => { thr = thr === undefined ? 12 : thr; if (!a || !b || a.w !== b.w || a.h !== b.h) return { err: 'size-mismatch' }; const k = a.k; const p0 = Math.max(0, Math.floor((xlo === undefined ? 0 : xlo) * k)); const p1 = Math.min(a.w, Math.ceil((xhi === undefined ? 1e9 : xhi) * k)); let X0 = 1e9, X1 = -1, Y0 = 1e9, Y1 = -1, n = 0; for (let y = 0; y < a.h; y++) for (let x = p0; x < p1; x++) { const i = (y * a.w + x) * 4; const dd = Math.abs(a.d[i] - b.d[i]) + Math.abs(a.d[i + 1] - b.d[i + 1]) + Math.abs(a.d[i + 2] - b.d[i + 2]); if (dd > thr) { n++; if (x < X0) X0 = x; if (x > X1) X1 = x; if (y < Y0) Y0 = y; if (y > Y1) Y1 = y; } } return n ? { x0: +(X0 / k).toFixed(1), x1: +(X1 / k).toFixed(1), y0: +(Y0 / k).toFixed(1), y1: +(Y1 / k).toFixed(1), h: +((Y1 - Y0 + 1) / k).toFixed(1), n } : null; },
    wait: async (f, ms) => { const t = Date.now(); for (;;) { let v = null; try { v = await f(); } catch (e) { v = null; } if (v) return v; if (Date.now() - t > (ms || 3000)) return null; await sleep(50); } },
    menu: async (text, ms) => { const it = await H.wait(() => { const ps = document.querySelectorAll('.ctx-menu'); const last = ps[ps.length - 1]; if (!last) return null; return [...last.querySelectorAll('.ctx-item')].find((e) => e.textContent.trim().indexOf(text) === 0 && e.getAttribute('aria-disabled') !== 'true') || null; }, ms || 3000); if (!it) throw new Error('menu item not found: ' + text); it.click(); await frames(); return true; },
    num: async (sel, val) => { const d = document.querySelector(sel); if (!d) throw new Error('no numdrag: ' + sel); d.dispatchEvent(new MouseEvent('dblclick', { bubbles: true })); const inp = await H.wait(() => document.querySelector('input.numdrag-input'), 1500); if (!inp) throw new Error('numdrag editor did not open: ' + sel); inp.value = String(val); inp.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); await frames(); return true; },
    setRange: (el, v) => { Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(el, String(v)); el.dispatchEvent(new Event('input', { bubbles: true })); },
    sel: (marker, v) => { const s = [...document.querySelectorAll('.pr-toolbar select')].find((x) => [...x.options].some((o) => o.value === marker)); if (!s) throw new Error('no select for ' + marker); if (s.value !== v) { s.value = v; s.dispatchEvent(new Event('change', { bubbles: true })); } return s.value; },
    focusPane: () => { const t = document.querySelector('.pr-toolbar'); ev(t, 'pointerdown', 4, 4, { buttons: 1 }); ev(t, 'pointerup', 4, 4, {}); },
    norm: async (div) => { H.sel('1/16', div || '1/16'); H.sel('major', 'off'); const t3 = document.querySelector('.pr-toolbar [aria-label="Triplet grid"]'); if (t3 && t3.getAttribute('aria-pressed') === 'true') t3.click(); await frames(); if (!document.querySelector('.pr-vel-wrap')) { document.querySelector('.pr-toolbar [aria-label^="Velocity / CC lanes"]').click(); await frames(); } for (let i = 0; i < 8; i++) { const m = [...document.querySelectorAll('[title="Remove this lane"]')]; if (!m.length) break; m[m.length - 1].click(); await frames(); } const lbl = document.querySelector('.pr-vel-label'); if (lbl && lbl.textContent.trim() !== 'VEL') { document.querySelector('.pr-lane-btn').click(); await H.menu('Velocity'); } await H.num('.pr-toolbar [role="spinbutton"][title="Quantize strength"]', 100); await H.num('.pr-notes-wrap [role="spinbutton"]', 100); await frames(); return true; },
    setup: async (div) => { if (!document.querySelector('.pr-root')) { let tab = document.querySelector('button[data-tab-id="pianoRoll"]'); if (!tab) { document.querySelector('.ms-item[aria-label="View"]').click(); await H.menu('Bottom Dock'); await sleep(250); tab = document.querySelector('button[data-tab-id="pianoRoll"]'); } if (!tab) throw new Error('no piano-roll dock tab'); tab.click(); if (!(await H.wait(() => document.querySelector('.pr-root'), 3000))) throw new Error('piano roll not mounted (popped out?)'); } const rz = document.querySelector('.resizer-h'); if (rz) { rz.dispatchEvent(new MouseEvent('dblclick', { bubbles: true })); await frames(); await H.drag(rz, 2, 2, 2, -220, {}, 4); await sleep(150); } H.key('Home'); await sleep(150); if (document.querySelector('.pr-empty')) { const btn = () => [...document.querySelectorAll('.pr-empty button')].find((b) => b.textContent.indexOf('Create a MIDI clip') === 0); if (!btn()) throw new Error('no create-clip button'); if (btn().disabled) { document.querySelector('[aria-label="Add track"]').click(); await H.menu('Add MIDI Track'); if (!(await H.wait(() => btn() && !btn().disabled, 5000))) throw new Error('MIDI track was not added'); } btn().click(); if (!(await H.wait(() => document.querySelector('.pr-notes-wrap'), 5000))) throw new Error('clip did not open'); } else { H.focusPane(); H.key('a', { ctrlKey: true }); await sleep(120); H.key('Delete'); if (!(await H.wait(() => H.count() === '0 notes', 5000))) throw new Error('could not empty the clip, count=' + H.count()); } await H.norm(div); const cv = H.notes(); if (cv.clientHeight < 120) throw new Error('notes canvas too short: ' + cv.clientHeight); return { count: H.count(), len: H.len(), pct: H.pct(), w: cv.clientWidth, h: cv.clientHeight, lanes: document.querySelectorAll('.pr-vel-wrap').length }; } };
  window.__prh = H; window.__obs = null; return 'installed';
}
